import type { SVGProps } from "react";

/**
 * Nike commerce-header-v2 icon set.
 * Paths transcribed from nike.com so the clone matches 1:1.
 * Every icon inherits `currentColor` and defaults to a 24px box.
 */

type IconProps = SVGProps<SVGSVGElement> & { size?: number };

function base({ size = 24, ...props }: IconProps) {
  return {
    width: size,
    height: size,
    viewBox: "0 0 24 24",
    role: "img" as const,
    focusable: false,
    "aria-hidden": true,
    fill: "none",
    ...props,
  };
}

export function SwooshIcon(props: IconProps) {
  return (
    <svg {...base(props)}>
      <path
        fill="currentColor"
        fillRule="evenodd"
        d="M21 8.719L7.836 14.303C6.74 14.768 5.818 15 5.075 15c-.836 0-1.445-.295-1.819-.884-.485-.76-.273-1.982.559-3.272.494-.754 1.122-1.446 1.734-2.108-.144.234-1.415 2.349-.025 3.345.275.2.666.298 1.147.298.386 0 .829-.063 1.316-.19L21 8.719z"
        clipRule="evenodd"
      />
    </svg>
  );
}

/**
 * Header logo swoosh. Uses a viewBox cropped tight to the mark so it renders at
 * Nike's true proportions (~wide, short) at a given pixel width — unlike the
 * square `SwooshIcon`, which leaves vertical whitespace.
 */
export function SwooshLogo({ width = 58, className }: { width?: number; className?: string }) {
  return (
    <svg
      width={width}
      height={(width * 6.6) / 18}
      viewBox="3.1 8.5 18 6.6"
      fill="none"
      role="img"
      aria-hidden
      className={className}
    >
      <path
        fill="currentColor"
        fillRule="evenodd"
        d="M21 8.719L7.836 14.303C6.74 14.768 5.818 15 5.075 15c-.836 0-1.445-.295-1.819-.884-.485-.76-.273-1.982.559-3.272.494-.754 1.122-1.446 1.734-2.108-.144.234-1.415 2.349-.025 3.345.275.2.666.298 1.147.298.386 0 .829-.063 1.316-.19L21 8.719z"
        clipRule="evenodd"
      />
    </svg>
  );
}

